fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let mut y: i32 = 0;
    while y < h {
        let mut x: i32 = 0;
        while x < w {
            let mut v: i32 = host::math::sin(x * 2 + t * 2);
            v = v + host::math::sin(y * 3 - t);
            v = v + host::math::sin(x + y + t);
            let mut b: i32 = (v + 768) / 6;
            if b > 255 { b = 255; }
            host::display::fill_rect(x, y, 8, 8, (b << 8) | (255 - b));
            x = x + 8;
        }
        y = y + 8;
    }
    host::display::present();
}
